<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientBackChannelLogoutUriAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientBackChannelLogoutUriAccessor trait.
 *
 * Covers null default, string/VO assignment via withBackChannelLogoutUri,
 * getBackChannelLogoutUri/backChannelLogoutUri accessors, and isBackChannelLogoutUriChanged with/without original.
 */
class TrustedClientBackChannelLogoutUriAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withBackChannelLogoutUri creates a new instance with the BackChannelLogoutUri set
     * from a string value, and getBackChannelLogoutUri returns the primitive string.
     */
    public function testWithBackChannelLogoutUriFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientBackChannelLogoutUriAccessorUnitTest();

        // Act
        $result = $holder->withBackChannelLogoutUri('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getBackChannelLogoutUri());
    }
    /**
     * Asserts that withbackChannelLogoutUri has access to the value object
     * from a string value, and getBackChannelLogoutUri returns the primitive string.
     */
    public function testWithBackChannelLogoutUriFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientBackChannelLogoutUriAccessorUnitTest();

        // Act
        $result = $holder->withBackChannelLogoutUri('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->backChannelLogoutUri()->value());
    }
    public function testChangedBackChannelLogoutUri(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientBackChannelLogoutUriAccessorUnitTest();
        $original = $holder->withBackChannelLogoutUri('one');
        $same = $holder->withBackChannelLogoutUri('one');
        $modified = $holder->withBackChannelLogoutUri('other');

        // Act
        $unchanged = $holder->isBackChannelLogoutUriChanged();
        $withSame = $original->isBackChannelLogoutUriChanged($same);
        $withDiferent = $original->isBackChannelLogoutUriChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientBackChannelLogoutUriAccessorUnitTest
{
    use TrustedClientBackChannelLogoutUriAccessor;
}
